import{_ as r,C as s,o as d,c as o,j as t,E as e,a as n,a3 as l}from"./chunks/framework.C6R8kWFE.js";const z=JSON.parse(`{"title":"3-hafta (Mentor)","description":"","frontmatter":{"title":"3-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"8-sinf (Foundation)","link":"/mentor/8-sinf-cs/"},"n":3,"bob":"II-bob · Zamonaviy IT yo‘nalishlari va raqamli infratuzilma asoslari","lessons":[{"g":7,"title":"Klaviaturada tez va to‘g‘ri yozish ko‘nikmalari (Touch typing)","lead":"Klaviaturaga qaramasdan 10 barmoqda chaqqon yozish san'ati, F va J sirlari, to'g'ri gavda ergonomikasi va yozish tezligini oshirish mashqlari.","link":"/mentor/8-sinf-cs/hafta-03/dars-1","slide":"/slaydlar/8-sinf-cs/hafta-03/dars-1.html","test":"/slaydlar/8-sinf-cs/hafta-03/dars-1-test.html"},{"g":8,"title":"Raqamli savodxonlik va raqamli madaniyat","lead":"Zamonaviy axborot olamida to'g'ri yo'l topish, tarmoq etiketi (Netiket), raqamli iz javobgarligi va feyk xabarlarni fosh qilish mahorati.","link":"/mentor/8-sinf-cs/hafta-03/dars-2","slide":"/slaydlar/8-sinf-cs/hafta-03/dars-2.html","test":"/slaydlar/8-sinf-cs/hafta-03/dars-2-test.html"},{"g":9,"title":"Raqamli transformatsiya tushunchasi","lead":"Hayot, ta'lim, davlat xizmatlari va biznesni zamonaviy texnologiyalar bilan yangilash, qog'ozsiz hujjat aylanishi hamda raqamli xavfsizlik asoslari.","link":"/mentor/8-sinf-cs/hafta-03/dars-3","slide":"/slaydlar/8-sinf-cs/hafta-03/dars-3.html","test":"/slaydlar/8-sinf-cs/hafta-03/dars-3-test.html"}],"test":"/slaydlar/8-sinf-cs/hafta-03/hafta-test.html"}},"headers":[],"relativePath":"mentor/8-sinf-cs/hafta-03/index.md","filePath":"mentor/8-sinf-cs/hafta-03/index.md"}`),h={name:"mentor/8-sinf-cs/hafta-03/index.md"},g={class:"blk"},y={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},m={class:"blk"},c={id:"baholash-mezoni",tabindex:"-1"};function u(x,a,k,q,v,b){const i=s("Icon");return d(),o("div",null,[t("div",g,[t("h2",y,[e(i,{name:"house"}),a[0]||(a[0]=n(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=t("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=l('<p>Har bir vazifa 20–30 daqiqa vaqt oladi. Vazifalar daftarda yoki kompyuterda alohida papkada saqlanadi.</p><h2 id="_7-dars-uchun-klaviaturada-tez-va-to-g-ri-yozish-ko-nikmalari" tabindex="-1">7-dars uchun (Klaviaturada tez va to‘g‘ri yozish ko‘nikmalari) <a class="header-anchor" href="#_7-dars-uchun-klaviaturada-tez-va-to-g-ri-yozish-ko-nikmalari" aria-label="Permalink to &quot;7-dars uchun (Klaviaturada tez va to‘g‘ri yozish ko‘nikmalari)&quot;">​</a></h2><p><strong>1-topshiriq: «O&#39;n barmoq bilan yozish mashg&#39;uloti»</strong></p><ol><li>Kompyuteringizda yoki onlayn trenajorda (klavogonki.ru, typingclub.com yoki keybr.com) kuniga 15 daqiqadan jami 3 kun touch typing mashqini bajaring.</li><li>Mashq davomida asosiy qator (<code>A S D F</code> va <code>J K L ;</code>) tugmalaridan barmoqlarni uzmasdan va klaviaturaga qaramasdan matn kiritishga intiling.</li><li>3-kunlik mashq natijangizni (WPM — daqiqadagi so&#39;zlar soni va aniqlik foizini) daftaringizga qayd eting (Masalan: 1-kun: 18 WPM, 85% aniqlik; 3-kun: 26 WPM, 94% aniqlik).</li></ol><p><strong>Kutiladigan natija:</strong> Touch typing texnikasini mustahkamlash, ko&#39;rish xotirasini rivojlantirish va WPM tezligini oshirish.</p><h2 id="_8-dars-uchun-raqamli-savodxonlik-va-raqamli-madaniyat" tabindex="-1">8-dars uchun (Raqamli savodxonlik va raqamli madaniyat) <a class="header-anchor" href="#_8-dars-uchun-raqamli-savodxonlik-va-raqamli-madaniyat" aria-label="Permalink to &quot;8-dars uchun (Raqamli savodxonlik va raqamli madaniyat)&quot;">​</a></h2><p><strong>2-topshiriq: «Shaxsiy raqamli iz auditi va Faktcheking»</strong></p><ol><li>O&#39;z ism va familiyangizni Google qidiruv tizimida qo&#39;shtirnoq ichida (<code>&quot;Ism Familiya&quot;</code>) qidiring. O&#39;zingiz haqingizda internetda qanday ma&#39;lumotlar, fotosuratlar yoki natijalar chiqishini tekshiring.</li><li>Ijtimoiy tarmoqlar (Telegram, Instagram yoki boshqa) profilingizdagi maxfiylik sozlamalarini ko&#39;rib chiqing: profilingiz, telefon raqamingiz va suratlaringiz begonalar uchun yopiqligiga ishonch hosil qiling.</li><li>So&#39;nggi paytlarda internetda yoki messenjerlarda tarqalgan bitta shubhali xabarni tanlang va uni darsda o&#39;rganilgan faktcheking qoidalari (rasmiy manba, birinchi manbaga havola, muallif) bo&#39;yicha tahlil qilib, 3-4 jumla bilan xulosangizni yozing.</li></ol><p><strong>Kutiladigan natija:</strong> O&#39;z raqamli izingizga mas&#39;uliyat bilan qarash va axborotning ishonchliligini tekshirish ko&#39;nikmasi.</p><h2 id="_9-dars-uchun-raqamli-transformatsiya-tushunchasi" tabindex="-1">9-dars uchun (Raqamli transformatsiya tushunchasi) <a class="header-anchor" href="#_9-dars-uchun-raqamli-transformatsiya-tushunchasi" aria-label="Permalink to &quot;9-dars uchun (Raqamli transformatsiya tushunchasi)&quot;">​</a></h2><p><strong>3-topshiriq: «my.gov.uz va raqamli jarayon loyihasi»</strong></p><ol><li>Ota-onangiz yoki ustozingiz yordamida <code>my.gov.uz</code> saytiga kiring. Portaldagi «Ta&#39;lim» yoki «Ijtimoiy ta&#39;minot» bo&#39;limidagi bitta xizmatni (masalan: maktabga qabul qilish, bolalar bog&#39;chasiga navbatga qo&#39;yish yoki ma&#39;lumotnoma olish) tanlang.</li><li>Bu xizmat ilgari (qog&#39;oz davrida) qanday olingan va hozir elektron shaklda qanday berilishini daftaringizda 2 ustunli jadvalda taqqoslang.</li><li>Kichik loyiha: O&#39;z maktabingizdagi bitta jarayonni (masalan, navbatchilik, oshxona to&#39;lovlari yoki sport inventarlarini olish) to&#39;liq raqamlashtirish bo&#39;yicha 3 bosqichli taklifingizni yozing (1. Qog&#39;ozsiz qilish, 2. Dastur yaratish, 3. Mobil ilova va avtomatika).</li></ol><p><strong>Kutiladigan natija:</strong> Davlat xizmatlari arxitekturasini tushunish va muammolarga raqamli transformatsion yechim loyihalash.</p><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><p>Dars boshida o&#39;quvchilarning typing trenajoridagi WPM ko&#39;rsatkichlarini solishtiring va kimda qanday o&#39;sish borligini rag&#39;batlantiring. 9-dars bo&#39;yicha berilgan kichik loyihalardagi ijodiy yondashuvlarni (maktab oshxonasi yoki sport zali loyihasi) guruhda muhokama qilish uchun 5 daqiqa ajrating.</p>',15))]),t("div",m,[t("h2",c,[e(i,{name:"list-checks"}),a[3]||(a[3]=n(" Baholash mezoni ",-1)),a[4]||(a[4]=t("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=l('<p>Dasturdagi mezonlarga asoslangan (100 ballik shkala): <strong>90–100 — 5</strong>, <strong>71–89 — 4</strong>, <strong>60–70 — 3</strong>, <strong>0–59 — 2</strong>.</p><p>Dasturda joriy nazorat (amaliy mashg&#39;ulotlar, darsdagi faollik, tezkor savol-javoblar va uy vazifasi) o&#39;quv jarayoni davomida o&#39;tkaziladi. Quyida 3-haftaning 3 ta darsi bo&#39;yicha har bir o&#39;quvchi ishtirokini qayd etish uchun baholash jadvali keltirilgan.</p><h2 id="mezonlar-har-bir-dars-uchun" tabindex="-1">Mezonlar (har bir dars uchun) <a class="header-anchor" href="#mezonlar-har-bir-dars-uchun" aria-label="Permalink to &quot;Mezonlar (har bir dars uchun)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th style="text-align:center;">Max ball</th><th>Tavsif</th></tr></thead><tbody><tr><td>Nazariya va tushunchalar</td><td style="text-align:center;">30</td><td>Touch typing qoidalari, Netiket va raqamli iz, Transformatsiya bosqichlarini bilishi</td></tr><tr><td>Amaliy ko&#39;nikmalar</td><td style="text-align:center;">30</td><td>10 barmoqda yozish trenajorlari, faktcheking tahlili, raqamli xizmatlar bilan ishlash</td></tr><tr><td>Raqamli madaniyat va mantiq</td><td style="text-align:center;">20</td><td>Ergonomika, xavfsiz muloqot odobi, transformatsiya keyslarini tahlil qilish mahorati</td></tr><tr><td>Uyga vazifa</td><td style="text-align:center;">20</td><td>Uy vazifasi to&#39;liq, sifatli va vaqtida bajarilgan</td></tr><tr><td><strong>Jami</strong></td><td style="text-align:center;"><strong>100</strong></td><td></td></tr></tbody></table><hr><h2 id="_7-dars-klaviaturada-tez-va-to-g-ri-yozish-ko-nikmalari" tabindex="-1">7-dars (Klaviaturada tez va to‘g‘ri yozish ko‘nikmalari) <a class="header-anchor" href="#_7-dars-klaviaturada-tez-va-to-g-ri-yozish-ko-nikmalari" aria-label="Permalink to &quot;7-dars (Klaviaturada tez va to‘g‘ri yozish ko‘nikmalari)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th style="text-align:center;">Nazariya /30</th><th style="text-align:center;">Amaliyot /30</th><th style="text-align:center;">Madaniyat /20</th><th style="text-align:center;">Uy vazifasi /20</th><th style="text-align:center;">Jami</th><th style="text-align:center;">Baho</th></tr></thead><tbody><tr><td>1.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>2.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>3.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><hr><h2 id="_8-dars-raqamli-savodxonlik-va-raqamli-madaniyat" tabindex="-1">8-dars (Raqamli savodxonlik va raqamli madaniyat) <a class="header-anchor" href="#_8-dars-raqamli-savodxonlik-va-raqamli-madaniyat" aria-label="Permalink to &quot;8-dars (Raqamli savodxonlik va raqamli madaniyat)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th style="text-align:center;">Nazariya /30</th><th style="text-align:center;">Amaliyot /30</th><th style="text-align:center;">Madaniyat /20</th><th style="text-align:center;">Uy vazifasi /20</th><th style="text-align:center;">Jami</th><th style="text-align:center;">Baho</th></tr></thead><tbody><tr><td>1.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>2.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>3.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><hr><h2 id="_9-dars-raqamli-transformatsiya-tushunchasi" tabindex="-1">9-dars (Raqamli transformatsiya tushunchasi) <a class="header-anchor" href="#_9-dars-raqamli-transformatsiya-tushunchasi" aria-label="Permalink to &quot;9-dars (Raqamli transformatsiya tushunchasi)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th style="text-align:center;">Nazariya /30</th><th style="text-align:center;">Amaliyot /30</th><th style="text-align:center;">Madaniyat /20</th><th style="text-align:center;">Uy vazifasi /20</th><th style="text-align:center;">Jami</th><th style="text-align:center;">Baho</th></tr></thead><tbody><tr><td>1.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>2.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>3.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><hr><h2 id="_3-hafta-yakuni" tabindex="-1">3-hafta yakuni <a class="header-anchor" href="#_3-hafta-yakuni" aria-label="Permalink to &quot;3-hafta yakuni&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th style="text-align:center;">7-dars</th><th style="text-align:center;">8-dars</th><th style="text-align:center;">9-dars</th><th style="text-align:center;">O&#39;rtacha ball</th><th style="text-align:center;">Yakuniy baho</th><th>Izoh va tavsiyalar</th></tr></thead><tbody><tr><td>1.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td></td></tr><tr><td>2.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td></td></tr><tr><td>3.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td></td></tr></tbody></table><hr><h2 id="hafta-xulosasi-va-keyingi-darslarga-ko-prik" tabindex="-1">Hafta xulosasi va keyingi darslarga ko&#39;prik <a class="header-anchor" href="#hafta-xulosasi-va-keyingi-darslarga-ko-prik" aria-label="Permalink to &quot;Hafta xulosasi va keyingi darslarga ko&#39;prik&quot;">​</a></h2><p>O&#39;quvchilar II bobning dastlabki uchta poydevor mavzusini o&#39;zlashtirishdi. Ular klaviaturada to&#39;g&#39;ri yozish, internetda madaniyatli va xavfsiz muloqot qilish hamda raqamli jamiyatda xizmatlarning qanday ishlashini o&#39;rgandilar. Keyingi 4-haftada global internet tarmog&#39;ining texnik arxitekturasi — IP-manzillar, domenlar, hosting, DNS va xavfsiz ulanish (HTTP/HTTPS) protokollari o&#39;rganiladi.</p>',19))])])}const p=r(h,[["render",u]]);export{z as __pageData,p as default};
